from pathlib import Path

main_path = Path('src/main.js')
style_path = Path('src/style.css')

main = main_path.read_text()

old_import = "import { clearLearnerProgress, loadLearnerProgress, recordLocalizationSession, saveLearnerProgress, summarizeLearnerProgress } from './learning/progressStore.js';\n"
new_import = old_import + "import { buildMasteryDashboard } from './learning/masteryDashboard.js';\n"
if old_import not in main:
    raise SystemExit('progress-store import anchor not found')
main = main.replace(old_import, new_import, 1)

old_tool = '''        <button id="localization-challenge-btn" class="tool challenge-accent">Localization challenge</button>\n        <button id="plexus-btn" class="tool">Brachial plexus</button>'''
new_tool = '''        <button id="localization-challenge-btn" class="tool challenge-accent">Localization challenge</button>\n        <button id="mastery-dashboard-btn" class="tool mastery-accent">Mastery dashboard</button>\n        <button id="plexus-btn" class="tool">Brachial plexus</button>'''
if old_tool not in main:
    raise SystemExit('tool-row anchor not found')
main = main.replace(old_tool, new_tool, 1)

old_card_anchor = '''      <section id="plexus-card" class="learning-card" hidden>'''
new_card = '''      <section id="mastery-dashboard-card" class="learning-card mastery-dashboard-card" hidden>\n        <div class="card-head">\n          <div>\n            <span class="label">Learning analytics</span>\n            <strong>Mastery dashboard</strong>\n          </div>\n          <span class="status-pill">Browser local</span>\n        </div>\n        <p class="mastery-intro">Track longitudinal localization performance without an account or backend.</p>\n\n        <div class="mastery-overview-stats">\n          <div><span>Sessions</span><b id="mastery-total-sessions">0</b></div>\n          <div><span>Accuracy</span><b id="mastery-overall-accuracy">—</b></div>\n          <div><span>Due review</span><b id="mastery-due-review">0</b></div>\n        </div>\n\n        <div class="mastery-momentum">\n          <span class="section-label">Recent momentum</span>\n          <b id="mastery-momentum-text">Complete at least two sessions to establish a trend.</b>\n        </div>\n\n        <div class="mastery-section">\n          <span class="section-label">Recent session accuracy</span>\n          <div id="mastery-session-trend" class="mastery-session-trend"></div>\n        </div>\n\n        <div class="mastery-section">\n          <span class="section-label">Lesion mastery states</span>\n          <div class="mastery-state-grid">\n            <div class="strong"><span>Strong</span><b id="mastery-count-strong">0</b></div>\n            <div class="practicing"><span>Practicing</span><b id="mastery-count-practicing">0</b></div>\n            <div class="developing"><span>Developing</span><b id="mastery-count-developing">0</b></div>\n            <div class="unseen"><span>Unseen</span><b id="mastery-count-unseen">0</b></div>\n          </div>\n        </div>\n\n        <div class="mastery-section">\n          <span class="section-label">All lesion patterns</span>\n          <div id="mastery-lesion-grid" class="mastery-lesion-grid"></div>\n        </div>\n\n        <div class="mastery-section">\n          <span class="section-label">Weakest practiced concepts</span>\n          <div id="mastery-weakest-list" class="mastery-weakest-list"></div>\n        </div>\n\n        <button id="mastery-review-btn" class="tool full mastery-review-btn" type="button">No review due</button>\n        <button id="mastery-clear-progress" class="mastery-clear-button" type="button">Clear saved progress</button>\n        <p class="simulator-note">Mastery labels summarize practice performance only. Progress stays in this browser and can be cleared at any time.</p>\n      </section>\n\n      <section id="plexus-card" class="learning-card" hidden>'''
if old_card_anchor not in main:
    raise SystemExit('plexus-card anchor not found')
main = main.replace(old_card_anchor, new_card, 1)

old_state = "let localizationChallengeMode = false;\nlet localizationChallengeDifficulty = 'adaptive';"
new_state = "let localizationChallengeMode = false;\nlet masteryDashboardMode = false;\nlet localizationChallengeDifficulty = 'adaptive';"
if old_state not in main:
    raise SystemExit('mastery state anchor not found')
main = main.replace(old_state, new_state, 1)

old_deactivate = '''  if (except !== 'localization-challenge') {\n    localizationChallengeMode = false;\n    document.querySelector('#localization-challenge-btn').classList.remove('active');\n    document.querySelector('#localization-challenge-card').hidden = true;\n  }\n  if (except !== 'plexus') {'''
new_deactivate = '''  if (except !== 'localization-challenge') {\n    localizationChallengeMode = false;\n    document.querySelector('#localization-challenge-btn').classList.remove('active');\n    document.querySelector('#localization-challenge-card').hidden = true;\n  }\n  if (except !== 'mastery-dashboard') {\n    masteryDashboardMode = false;\n    document.querySelector('#mastery-dashboard-btn').classList.remove('active');\n    document.querySelector('#mastery-dashboard-card').hidden = true;\n  }\n  if (except !== 'plexus') {'''
if old_deactivate not in main:
    raise SystemExit('deactivate anchor not found')
main = main.replace(old_deactivate, new_deactivate, 1)

old_pointer = '''  if (quizMode) return answerQuiz(hit.userData.structureKey);\n  if (localizationChallengeMode) return;\n  setSelected(hit);'''
new_pointer = '''  if (quizMode) return answerQuiz(hit.userData.structureKey);\n  if (localizationChallengeMode || masteryDashboardMode) return;\n  setSelected(hit);'''
if old_pointer not in main:
    raise SystemExit('pointer anchor not found')
main = main.replace(old_pointer, new_pointer, 1)

old_progress_function = '''function renderPersistentChallengeProgress() {\n  const summary = challengeProgressSummary();\n  document.querySelector('#challenge-lifetime-sessions').textContent = String(summary.sessions);\n  document.querySelector('#challenge-lifetime-accuracy').textContent = summary.accuracy == null\n    ? '—'\n    : `${Math.round(summary.accuracy * 100)}%`;\n  document.querySelector('#challenge-review-count').textContent = String(summary.reviewQueue.length);\n\n  const attemptedNerves = summary.nerves\n    .filter((item) => item.attempts > 0)\n    .sort((a, b) => (a.accuracy ?? 0) - (b.accuracy ?? 0) || b.attempts - a.attempts);\n  const weakest = attemptedNerves[0];\n  document.querySelector('#challenge-persistent-focus').textContent = weakest\n    ? `Current focus: ${weakest.name} · ${weakest.mastery} · ${Math.round((weakest.accuracy ?? 0) * 100)}% across ${weakest.attempts} attempt${weakest.attempts === 1 ? '' : 's'}.`\n    : 'Complete a session to build a mastery profile.';\n}\n'''
new_progress_function = old_progress_function + '''\nfunction formatMasterySessionDate(value) {\n  if (!value) return 'Session';\n  const date = new Date(value);\n  if (Number.isNaN(date.getTime())) return 'Session';\n  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });\n}\n\nfunction renderMasteryDashboard() {\n  const summary = challengeProgressSummary();\n  const dashboard = buildMasteryDashboard(learnerProgress, summary);\n\n  document.querySelector('#mastery-total-sessions').textContent = String(dashboard.totalSessions);\n  document.querySelector('#mastery-overall-accuracy').textContent = dashboard.overallAccuracy == null\n    ? '—'\n    : `${Math.round(dashboard.overallAccuracy * 100)}%`;\n  document.querySelector('#mastery-due-review').textContent = String(dashboard.dueReviewCount);\n\n  const momentum = dashboard.momentum;\n  let momentumText = 'Complete at least two sessions to establish a trend.';\n  if (momentum.direction === 'steady') momentumText = 'Performance is steady across recent sessions.';\n  if (momentum.direction === 'up') momentumText = `Recent accuracy is up ${Math.round(Math.abs(momentum.delta) * 100)} percentage points.`;\n  if (momentum.direction === 'down') momentumText = `Recent accuracy is down ${Math.round(Math.abs(momentum.delta) * 100)} percentage points — prioritize review.`;\n  document.querySelector('#mastery-momentum-text').textContent = momentumText;\n\n  const trend = document.querySelector('#mastery-session-trend');\n  trend.innerHTML = dashboard.recentSessions.length\n    ? dashboard.recentSessions.map((session) => {\n        const percent = session.accuracy == null ? 0 : Math.round(session.accuracy * 100);\n        const height = Math.max(8, percent);\n        const mode = challengeDifficultyLabel(session.mode);\n        return `<div class="mastery-trend-item" title="${mode} · ${percent}%"><div class="mastery-trend-bar-wrap"><span class="mastery-trend-bar" style="height:${height}%"></span></div><b>${percent}%</b><span>${formatMasterySessionDate(session.completedAt)}</span></div>`;\n      }).join('')\n    : '<p class="mastery-empty">Complete a localization session to start the trend.</p>';\n\n  document.querySelector('#mastery-count-strong').textContent = String(dashboard.masteryCounts.Strong);\n  document.querySelector('#mastery-count-practicing').textContent = String(dashboard.masteryCounts.Practicing);\n  document.querySelector('#mastery-count-developing').textContent = String(dashboard.masteryCounts.Developing);\n  document.querySelector('#mastery-count-unseen').textContent = String(dashboard.masteryCounts.Unseen);\n\n  document.querySelector('#mastery-lesion-grid').innerHTML = dashboard.lesions.map((lesion) => {\n    const percent = lesion.accuracy == null ? 0 : Math.round(lesion.accuracy * 100);\n    const accuracyLabel = lesion.attempts ? `${percent}% · ${lesion.correct}/${lesion.attempts}` : 'Not practiced';\n    const statusClass = lesion.mastery.toLowerCase();\n    return `<div class="mastery-lesion-row ${statusClass}"><div class="mastery-lesion-copy"><span>${lesion.nerveName}</span><b>${lesion.label}</b></div><div class="mastery-lesion-score"><em>${lesion.mastery}</em><span>${accuracyLabel}</span></div><div class="mastery-meter"><span style="width:${lesion.attempts ? Math.max(4, percent) : 0}%"></span></div></div>`;\n  }).join('');\n\n  document.querySelector('#mastery-weakest-list').innerHTML = dashboard.weakest.length\n    ? dashboard.weakest.map((lesion) => {\n        const percent = Math.round((lesion.accuracy ?? 0) * 100);\n        return `<div><b>${lesion.nerveName} · ${lesion.label}</b><span>${percent}% across ${lesion.attempts} attempt${lesion.attempts === 1 ? '' : 's'} · ${lesion.mastery}</span></div>`;\n      }).join('')\n    : '<p class="mastery-empty">No practiced lesion patterns yet.</p>';\n\n  const reviewButton = document.querySelector('#mastery-review-btn');\n  reviewButton.disabled = dashboard.dueReviewCount === 0;\n  reviewButton.textContent = dashboard.dueReviewCount\n    ? `Practice ${dashboard.dueReviewCount} due review${dashboard.dueReviewCount === 1 ? '' : 's'}`\n    : 'No review due';\n}\n'''
if old_progress_function not in main:
    raise SystemExit('persistent-progress function anchor not found')
main = main.replace(old_progress_function, new_progress_function, 1)

old_clear = '''document.querySelector('#challenge-clear-progress').addEventListener('click', () => {\n  if (!window.confirm('Clear all Anatomica localization progress stored in this browser?')) return;\n  learnerProgress = clearLearnerProgress();\n  renderPersistentChallengeProgress();\n  syncChallengeDifficultyButtons();\n});\n\ndocument.querySelector('#localization-challenge-btn').addEventListener('click', () => {'''
new_clear = '''function clearAllLearnerProgress() {\n  if (!window.confirm('Clear all Anatomica localization progress stored in this browser?')) return;\n  learnerProgress = clearLearnerProgress();\n  renderPersistentChallengeProgress();\n  renderMasteryDashboard();\n  syncChallengeDifficultyButtons();\n}\n\ndocument.querySelector('#challenge-clear-progress').addEventListener('click', clearAllLearnerProgress);\ndocument.querySelector('#mastery-clear-progress').addEventListener('click', clearAllLearnerProgress);\n\ndocument.querySelector('#localization-challenge-btn').addEventListener('click', () => {'''
if old_clear not in main:
    raise SystemExit('clear-progress anchor not found')
main = main.replace(old_clear, new_clear, 1)

old_after_challenge = '''document.querySelector('#localization-challenge-btn').addEventListener('click', () => {\n  const nextState = !localizationChallengeMode;\n  deactivateStudyModes('localization-challenge');\n  localizationChallengeMode = nextState;\n  document.querySelector('#localization-challenge-btn').classList.toggle('active', localizationChallengeMode);\n  document.querySelector('#localization-challenge-card').hidden = !localizationChallengeMode;\n  if (localizationChallengeMode) {\n    startLocalizationChallengeSession(localizationChallengeDifficulty);\n  } else {\n    restoreAll();\n    setModeBadge('');\n    fitCameraToAnatomy();\n  }\n});\n\nconst branchContainer = document.querySelector('#plexus-branches');'''
new_after_challenge = '''document.querySelector('#localization-challenge-btn').addEventListener('click', () => {\n  const nextState = !localizationChallengeMode;\n  deactivateStudyModes('localization-challenge');\n  localizationChallengeMode = nextState;\n  document.querySelector('#localization-challenge-btn').classList.toggle('active', localizationChallengeMode);\n  document.querySelector('#localization-challenge-card').hidden = !localizationChallengeMode;\n  if (localizationChallengeMode) {\n    startLocalizationChallengeSession(localizationChallengeDifficulty);\n  } else {\n    restoreAll();\n    setModeBadge('');\n    fitCameraToAnatomy();\n  }\n});\n\ndocument.querySelector('#mastery-dashboard-btn').addEventListener('click', () => {\n  const nextState = !masteryDashboardMode;\n  deactivateStudyModes('mastery-dashboard');\n  masteryDashboardMode = nextState;\n  document.querySelector('#mastery-dashboard-btn').classList.toggle('active', masteryDashboardMode);\n  document.querySelector('#mastery-dashboard-card').hidden = !masteryDashboardMode;\n  if (masteryDashboardMode) {\n    renderMasteryDashboard();\n    setChallengeNeutralViewer();\n    setModeBadge('Mastery Dashboard · Browser-local learning analytics');\n  } else {\n    restoreAll();\n    setModeBadge('');\n    fitCameraToAnatomy();\n  }\n});\n\ndocument.querySelector('#mastery-review-btn').addEventListener('click', () => {\n  if (challengeProgressSummary().reviewQueue.length === 0) return;\n  deactivateStudyModes('localization-challenge');\n  masteryDashboardMode = false;\n  document.querySelector('#mastery-dashboard-btn').classList.remove('active');\n  document.querySelector('#mastery-dashboard-card').hidden = true;\n  localizationChallengeMode = true;\n  document.querySelector('#localization-challenge-btn').classList.add('active');\n  document.querySelector('#localization-challenge-card').hidden = false;\n  startLocalizationChallengeSession('review');\n});\n\nconst branchContainer = document.querySelector('#plexus-branches');'''
if old_after_challenge not in main:
    raise SystemExit('challenge listener anchor not found')
main = main.replace(old_after_challenge, new_after_challenge, 1)

main_path.write_text(main)

style = style_path.read_text()
style += '''\n\n/* v0.3.7 longitudinal mastery dashboard */\n.tool.mastery-accent { border-color: #4e657d; }\n.tool.mastery-accent.active { background: #203344; border-color: #7398ba; color: #edf6ff; }\n.mastery-dashboard-card { border-color: #304359; }\n.mastery-intro { margin: 14px 0 0; color: #98a8ba; font-size: 12px; line-height: 1.5; }\n.mastery-overview-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; }\n.mastery-overview-stats div { padding: 10px; border: 1px solid #2d3d4d; border-radius: 11px; background: #0f161e; }\n.mastery-overview-stats span { display: block; color: #77889a; font-size: 9px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }\n.mastery-overview-stats b { display: block; margin-top: 5px; color: #e4edf5; font-size: 17px; }\n.mastery-momentum { margin-top: 14px; padding: 12px; border: 1px solid #2d4052; border-radius: 11px; background: #101923; }\n.mastery-momentum .section-label { margin-bottom: 6px; }\n.mastery-momentum b { color: #cdd9e5; font-size: 12px; line-height: 1.45; }\n.mastery-section { margin-top: 18px; padding-top: 15px; border-top: 1px solid #273340; }\n.mastery-session-trend { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 7px; align-items: end; min-height: 132px; }\n.mastery-trend-item { display: grid; grid-template-rows: 80px auto auto; gap: 4px; text-align: center; min-width: 0; }\n.mastery-trend-bar-wrap { display: flex; align-items: end; justify-content: center; height: 80px; border-radius: 7px; background: #0d141c; overflow: hidden; }\n.mastery-trend-bar { display: block; width: 72%; min-height: 6px; border-radius: 5px 5px 2px 2px; background: linear-gradient(180deg, #78a0c5, #395b78); }\n.mastery-trend-item b { color: #dce7f0; font-size: 10px; }\n.mastery-trend-item > span { color: #6f7e8e; font-size: 9px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.mastery-state-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }\n.mastery-state-grid div { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px; border: 1px solid #303b47; border-radius: 10px; background: #10161d; }\n.mastery-state-grid span { font-size: 10px; font-weight: 700; }\n.mastery-state-grid b { font-size: 16px; }\n.mastery-state-grid .strong { border-color: #315e45; color: #cfe9d9; }\n.mastery-state-grid .practicing { border-color: #4b5f76; color: #d2e2f2; }\n.mastery-state-grid .developing { border-color: #6f5c2c; color: #eadfbf; }\n.mastery-state-grid .unseen { color: #929eaa; }\n.mastery-lesion-grid { display: grid; gap: 8px; }\n.mastery-lesion-row { display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; padding: 11px; border: 1px solid #2b3540; border-radius: 11px; background: #0f151c; }\n.mastery-lesion-copy span { display: block; color: #748596; font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: .07em; }\n.mastery-lesion-copy b { display: block; margin-top: 3px; color: #dce4ed; font-size: 11.5px; }\n.mastery-lesion-score { text-align: right; }\n.mastery-lesion-score em { display: block; font-size: 10px; font-style: normal; font-weight: 700; }\n.mastery-lesion-score span { display: block; margin-top: 3px; color: #7d8a98; font-size: 9.5px; }\n.mastery-lesion-row.strong .mastery-lesion-score em { color: #8fc8a6; }\n.mastery-lesion-row.practicing .mastery-lesion-score em { color: #9db7d2; }\n.mastery-lesion-row.developing .mastery-lesion-score em { color: #d4bc78; }\n.mastery-lesion-row.unseen .mastery-lesion-score em { color: #7d8995; }\n.mastery-meter { grid-column: 1 / -1; height: 5px; overflow: hidden; border-radius: 999px; background: #1b242e; }\n.mastery-meter span { display: block; height: 100%; border-radius: inherit; background: #688eaf; }\n.mastery-lesion-row.strong .mastery-meter span { background: #4f8c69; }\n.mastery-lesion-row.developing .mastery-meter span { background: #92753c; }\n.mastery-weakest-list { display: grid; gap: 7px; }\n.mastery-weakest-list div { display: grid; gap: 3px; padding: 10px; border-left: 3px solid #7b5f77; background: #17131a; }\n.mastery-weakest-list b { color: #dfd0dd; font-size: 11px; }\n.mastery-weakest-list span { color: #948795; font-size: 10px; line-height: 1.4; }\n.mastery-empty { margin: 0; color: #758392; font-size: 11px; line-height: 1.45; }\n.mastery-review-btn:not(:disabled) { border-color: #577b70; background: #20342e; color: #e2f2ec; }\n.mastery-clear-button { width: 100%; margin-top: 9px; border: 0; background: transparent; color: #748294; cursor: pointer; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; }\n.mastery-clear-button:hover { color: #c7d1dc; }\n@media (max-width: 560px) {\n  .mastery-session-trend { grid-template-columns: repeat(3, minmax(0, 1fr)); row-gap: 12px; }\n  .mastery-overview-stats { grid-template-columns: 1fr; }\n}\n'''
style_path.write_text(style)

print('Applied Anatomica v0.3.7 longitudinal mastery dashboard.')
